def find_kth(a, b, k):
    """Return the k-th smallest element (1-indexed) of two sorted arrays, in O(log min(m, n)) time."""
    if not 1 <= k <= len(a) + len(b):
        raise ValueError("k must be between 1 and len(a) + len(b)")

    # Binary search over how many elements of the shorter array come first.
    if len(a) > len(b):
        a, b = b, a

    lo = max(0, k - len(b))
    hi = min(k, len(a))
    while lo < hi:
        i = (lo + hi) // 2      # elements taken from a
        j = k - i               # elements taken from b
        if a[i] < b[j - 1]:
            lo = i + 1
        else:
            hi = i

    i = lo
    j = k - i
    # The k-th element is the larger of the last elements taken from each array.
    candidates = []
    if i > 0:
        candidates.append(a[i - 1])
    if j > 0:
        candidates.append(b[j - 1])
    return max(candidates)


assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
